package com.bernaferrari.changedetection

import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.remember
import com.bernaferrari.changedetection.repo.ConstraintsRequired
import com.bernaferrari.changedetection.repo.Site
import com.bernaferrari.changedetection.repo.Snap
import com.bernaferrari.changedetection.repo.source.local.SitesDao
import com.bernaferrari.changedetection.repo.source.local.SnapsDao
import com.bernaferrari.changedetection.util.FileStorage
import com.bernaferrari.changedetection.di.initKoin
import kotlin.io.encoding.Base64
import kotlin.time.Clock
import org.koin.mp.KoinPlatformTools

fun initChangeDetectionDemo() {
    initKoin()
}

/** Wasm supplies demo data; every screen and component still comes from the shared application. */
@Composable
fun ChangeDetectionDemoHost() {
    val koin = remember { KoinPlatformTools.defaultContext().get() }
    val sitesDao = remember(koin) { koin.get<SitesDao>() }
    val snapsDao = remember(koin) { koin.get<SnapsDao>() }
    val fileStorage = remember(koin) { koin.get<FileStorage>() }

    LaunchedEffect(Unit) {
        if (sitesDao.getSitesList().isEmpty()) {
            seedDemoData(sitesDao, snapsDao, fileStorage)
        } else {
            restoreDemoData(sitesDao, snapsDao, fileStorage)
        }
    }

    ChangeDetectionRootApp(platformActions = PlatformActions(appVersion = "Web demo"))
}

/** The browser demo keeps both Room data and snapshot payloads in memory. */
private suspend fun restoreDemoData(
    sitesDao: SitesDao,
    snapsDao: SnapsDao,
    fileStorage: FileStorage,
) {
    mapOf(
        "espresso-old" to "Espresso machine — $699",
        "espresso-new" to "Espresso machine — $649",
        "tickets-current" to "Sale opens Friday at 10:00",
    ).forEach { (id, content) -> fileStorage.writeBytes(id, content.encodeToByteArray()) }

    val now = Clock.System.now().toEpochMilliseconds()
    sitesDao.getSiteById("release-notes")?.let { site ->
        sitesDao.updateSite(site.copy(isBrowser = true, timestamp = now - 18 * 60_000))
    }
    snapsDao.deleteAllSnapsForSite("release-notes")
    seedImageVersion(snapsDao, fileStorage, "release-old", now - 172_800_000, DEMO_RELEASE_OLD_JPEG)
    seedImageVersion(snapsDao, fileStorage, "release-new", now - 18 * 60_000, DEMO_RELEASE_NEW_JPEG)
}

private suspend fun seedDemoData(
    sitesDao: SitesDao,
    snapsDao: SnapsDao,
    fileStorage: FileStorage,
) {
    val now = Clock.System.now().toEpochMilliseconds()
    val sites = listOf(
        demoSite("permit", "City permit status", "https://city.example.gov/permit/4182", now - 24 * 60_000, 0xFFFFB77D, successful = false),
        demoSite("espresso", "Espresso machine stock", "https://store.example.com/espresso", now - 2 * 60_000, 0xFFB8C4FF),
        demoSite("release-notes", "Release notes", "https://docs.example.com/releases", now - 18 * 60_000, 0xFF8DE3C2, isBrowser = true),
        demoSite("tickets", "Concert tickets", "https://events.example.com/tickets", now - 7 * 60_000, 0xFFFFB3C7),
        demoSite("research", "Research report", "https://research.example.org/report", now - 86_400_000, 0xFFD0BCFF, syncEnabled = false),
    )
    sites.forEach { sitesDao.insertSite(it) }

    seedVersion(snapsDao, fileStorage, "espresso-old", "espresso", now - 86_400_000, "Espresso machine — $699")
    seedVersion(snapsDao, fileStorage, "espresso-new", "espresso", now - 2 * 60_000, "Espresso machine — $649")
    seedImageVersion(snapsDao, fileStorage, "release-old", now - 172_800_000, DEMO_RELEASE_OLD_JPEG)
    seedImageVersion(snapsDao, fileStorage, "release-new", now - 18 * 60_000, DEMO_RELEASE_NEW_JPEG)
    seedVersion(snapsDao, fileStorage, "tickets-current", "tickets", now - 86_400_000, "Sale opens Friday at 10:00")
}

private fun demoSite(
    id: String,
    title: String,
    url: String,
    timestamp: Long,
    color: Long,
    successful: Boolean = true,
    syncEnabled: Boolean = true,
    isBrowser: Boolean = false,
) = Site(
    title = title,
    url = url,
    timestamp = timestamp,
    id = id,
    isSuccessful = successful,
    isBrowser = isBrowser,
    threshold = 0,
    isRead = false,
    isSyncEnabled = syncEnabled,
    isNotificationEnabled = true,
    notes = "",
    colors = color.toInt() to color.toInt(),
    constraints = ConstraintsRequired(false, false, false, false),
)

private suspend fun seedVersion(
    snapsDao: SnapsDao,
    fileStorage: FileStorage,
    id: String,
    siteId: String,
    timestamp: Long,
    content: String,
) {
    val bytes = content.encodeToByteArray()
    snapsDao.insertSnap(
        Snap(
            snapId = id,
            siteId = siteId,
            timestamp = timestamp,
            contentType = "text/plain",
            contentCharset = "UTF-8",
            contentSize = bytes.size,
        ),
    )
    fileStorage.writeBytes(id, bytes)
}

private suspend fun seedImageVersion(
    snapsDao: SnapsDao,
    fileStorage: FileStorage,
    id: String,
    timestamp: Long,
    encodedBytes: String,
) {
    val bytes = Base64.decode(encodedBytes)
    snapsDao.insertSnap(
        Snap(
            snapId = id,
            siteId = "release-notes",
            timestamp = timestamp,
            contentType = "image/jpeg",
            contentCharset = "",
            contentSize = bytes.size,
        ),
    )
    fileStorage.writeBytes(id, bytes)
}

private const val DEMO_RELEASE_OLD_JPEG = ""
private const val DEMO_RELEASE_NEW_JPEG = ""
